    "Aceitar mensagens de grupos, canais e comunidades — desligue para receber só a conversa direta com o bot": "接收来自群组、频道和社区的消息 — 关闭后只接收与机器人的私聊",
    "Aceitar mensagens de grupos, canais e comunidades — desligue para receber só a conversa direta com o número da live": "接收来自群组、频道和社区的消息 — 关闭后只接收与直播号码的私聊",
    "Só a conversa direta está entrando — ligue os grupos acima para usar este campo.": "目前只有私聊会进来 — 要使用这个输入框，请先在上面打开群组。",
