    // 📱 v0.139: a personalização do QR
    "📱 O código em si": "📱 码本身",
    "As cores acima são do cartão que segura o QR; estas aqui são do código em si. Nada disto muda o que o QR carrega — só o desenho.": "上面的颜色属于托着二维码的卡片，这里的属于码本身。这些都不会改变二维码里装的东西 —— 只改外观。",
    "Clássico": "经典",
    "Suave": "柔和",
    "Pontinhos": "圆点",
    "Losango": "菱形",
    "Sem fundo": "无背景",
