    "🕐 Relógio, cronômetro e timer": "🕐 时钟、秒表和倒计时",
    "Ajustes do widget 🕐 do painel. A aparência (cores, tamanho, posição, animações) fica no": "面板上 🕐 小组件的设置。外观（颜色、大小、位置、动画）在",
    "🧩 Personalizar widgets": "🧩 自定义小组件",
    "logo acima, escolhendo \"🕐 Relógio / cronômetro / timer\".": "就在上面，选择\"🕐 时钟 / 秒表 / 倒计时\"即可调整。",
    "🌍 Fuso horário": "🌍 时区",
    "\"Do computador\" segue o relógio do Windows. Escolha outro fuso se você transmite para um público de outro país — o relógio da tela usa o fuso escolhido.": "\"跟随电脑\"会跟着 Windows 的时钟走。如果你面向其他国家的观众直播，就换一个时区——画面上的时钟会用你选的时区。",
    "🔊 Som quando o timer acabar": "🔊 倒计时结束时的声音",
    "⏰ Alerta padrão do OBS Social": "⏰ OBS Social 默认提示音",
    "🖼️ Seus overlays": "🖼️ 你的叠加层",
    "(logo abaixo) — qualquer formato, até": "（就在下面）——任何格式，最长",
    "Volume:": "音量：",
    "Onde o som toca": "声音在哪里播放",
    "Controlar áudio via OBS": "通过 OBS 控制音频",
    "na fonte Navegador).": "在浏览器来源上）。",
    "📢 Tirar o Aviso da tela automaticamente (Timer e Avisos trabalhando juntos)": "📢 自动把公告从画面上撤下（倒计时和公告配合工作）",
    "✨ Piscar o número quando zerar": "✨ 归零时让数字闪烁",
    "📅 Mostrar a data junto da hora no painel (desligado = só a hora)": "📅 在面板上把日期显示在时间旁边（关闭＝只显示时间）",
    "⏳ Reta final do timer (antes de zerar)": "⏳ 倒计时的最后冲刺（归零之前）",
    "✨ Piscar o número na reta final": "✨ 在最后冲刺时让数字闪烁",
    "Começa a quantos segundos do fim (1 a 60)": "从结束前几秒开始（1 到 60）",
    "Cor da reta final": "最后冲刺的颜色",
    "🔴 Quando o tempo acabar (no 00:00)": "🔴 时间到的时候（00:00）",
    "Pisca por quantos segundos (0 = sem parar; máx. 300)": "闪烁多少秒（0＝一直闪；最多 300）",
    "Cor da piscada do fim": "结束闪烁的颜色",
    "📢 O Aviso piscando junto com o timer": "📢 公告和倒计时一起闪烁",
    "📢 Piscar o Aviso na tela na reta final": "📢 在最后冲刺时让画面上的公告闪烁",
    "Cor do Aviso enquanto pisca": "闪烁时公告的颜色",
    "O ↺ da cor do Aviso tira a troca de cor: ele pisca mantendo a cor normal do texto.": "公告颜色的 ↺ 会取消换色：它会保持文字本来的颜色闪烁。",
    "O que acontece na tela quando você clica em 🎲": "点击 🎲 时画面上会发生什么",
    "Sortear": "抽奖",
    ". As fichas extras de subs e membros ficam no próprio botão 🎁 do painel; a aparência do pódio fica no": "。订阅者和会员的额外抽奖券在 🎁 按钮里；领奖台的外观在",
    ", escolhendo \"🎁 Sorteio\".": "中选择\"🎁 抽奖\"来设置。",
    "🎲 Tempo que o dado fica rodando na tela (0 a 15 segundos)": "🎲 骰子在画面上滚动的时间（0 到 15 秒）",
    "É o suspense antes do pódio aparecer.": "这是领奖台出现前的悬念。",
    "vai direto para os ganhadores, sem dado.": "会跳过骰子，直接公布获奖者。",
    "🔊 Som do dado": "🔊 骰子声音",
    "🎲 Dado padrão do OBS Social": "🎲 OBS Social 默认骰子",
    "Quicar e cair (bounce)": "弹跳落下",
    "Rodopiar sem parar": "不停旋转",
    "Desfocar e voltar": "模糊后复原",
    "Chacoalhar": "抖动",
    "Texto do comentário ao lado do nome": "评论正文放在名字旁边",
    "(desligado = embaixo do nome, como sempre foi)": "（关闭＝放在名字下面，和以前一样）",
    "É o mesmo formato do 💬 Chat ao vivo fixo: o nome e o comentário na mesma linha, com o horário à direita. Vale para a aba Ao vivo, para as colunas e para as outras listas do painel.": "和 💬 固定直播聊天一样的排版：名字和评论在同一行，时间在右边。直播标签页、分栏视图和面板里的其他列表都适用。",
    "📄 Texto do comentário embaixo do nome (igual ao painel ao vivo)": "📄 评论正文放在名字下面（和直播面板一样）",
    "🔐 O navegador diz \"a conexão com este site não é segura\". Isso é problema?": "🔐 浏览器提示\"你与此网站的连接不安全\"。这有问题吗？",
    "Não é problema.": "没有问题。",
    "Esse recado aparece em todo endereço que começa com \"http://\" e não quer dizer que alguém esteja bisbilhotando o seu painel.": "这条提示会出现在每一个以\"http://\"开头的地址上，并不表示有人在偷看你的面板。",
    "No seu computador (localhost):": "在你自己的电脑上（localhost）：",
    "os navegadores tratam o localhost como origem confiável por definição. Esses dados nunca saem da máquina — não passam por cabo, Wi-Fi nem internet. O aviso ali é só o texto padrão do \"http://\".": "浏览器按定义把 localhost 视为可信来源。这些数据永远不会离开这台机器——不走网线、不走 Wi-Fi、不走互联网。那句提示只是\"http://\"的标准文案。",
    "No endereço da sua rede (192.168...):": "在你的局域网地址上（192.168...）：",
    "os dados andam apenas entre o seu computador e o aparelho do seu mod, passando pelo seu roteador. Nada disso vai para a internet.": "数据只在你的电脑和管理员的设备之间流动，经过你自己的路由器。这些都不会上互联网。",
    "Por que o OBS Social não usa \"https\"?": "那 OBS Social 为什么不用\"https\"？",
    "O cadeado do https depende de um certificado, e certificado de verdade só é emitido para um nome de site público, como \"seusite.com.br\". Um endereço caseiro de rede não tem nome público — e nem deveria ter, porque ele não existe fora da sua casa.": "https 的小锁依赖证书，而真正的证书只会颁发给公开的网站名，比如\"yoursite.com\"。家用局域网地址没有公开名字——也不该有，因为它在你家之外并不存在。",
    "E um certificado feito em casa?": "那自己做一个证书呢？",
    "Seria pior: o navegador passaria a mostrar uma tela vermelha de perigo toda vez, em cada aparelho, e para tirá-la você teria que instalar um arquivo de confiança no sistema — exatamente o tipo de coisa que faz o antivírus apitar. Por isso o OBS Social não faz isso.": "那样更糟：浏览器会在每台设备上每次都弹出红色危险页面；要去掉它，你还得往系统里安装一个信任文件——这正是杀毒软件会报警的那类操作。所以 OBS Social 不这么做。",
    "O que realmente protege você aqui": "在这里真正保护你的",
    "é o que está logo abaixo: o programa só aceita conexões da sua própria rede, você escolhe o que a rede pode usar e ainda pode colocar uma senha.": "就是下面这些：程序只接受来自你自己网络的连接，你可以选择网络能用哪些功能，还能设置密码。",
    "🔟 Mostrar os décimos de segundo no cronômetro (00:05.4)": "🔟 秒表显示十分之一秒（00:05.4）",
    "🔇 Clique aqui para liberar o som dos alertas": "🔇 点这里允许提醒声音",
    "🔇 Toque aqui para liberar o som dos alertas": "🔇 点这里允许提醒声音",
    "O navegador só toca som depois de um clique na página": "浏览器只有在页面被点击后才会播放声音",
    "Toque uma vez para o navegador liberar o som": "轻点一次，让浏览器允许声音",
    "Se o navegador disser \"não é seguro\", é só porque o endereço é da sua rede e não da internet — a explicação completa está em ⚙️ Configurações → 🔗 URLs para o OBS.": "如果浏览器说\"不安全\"，只是因为这个地址属于你的网络而不是互联网——完整说明在 ⚙️ 设置 → 🔗 OBS 用的 URL 里。",
