    "Voltar ao tema padrão do OBS Social? As cores e ajustes que você mudou aqui serão descartados.": "要恢复 OBS Social 的默认主题吗？你在这里更改的颜色和设置将被丢弃。",
    "Não consegui ler esse arquivo de tema. Ele precisa ser um tema salvo pelo OBS Social.": "无法读取该主题文件。它必须是 OBS Social 保存的主题。",
    "Carregar este tema? Ele substitui as cores e os ajustes de aparência que estão valendo agora.": "要加载此主题吗？它会替换当前生效的颜色和外观设置。",
    '🗄️ Logs e dados': "🗄️ 日志与数据",
    "🧹 Limpeza de dados": "🧹 数据清理",
