    'Limpar a tela: tira destaque, sorteio, likômetro e winstreak. O QR code fica.': '清空屏幕：移除精选评论、抽奖、点赞计和连胜。二维码保留。',
    'Busca comentários pelo nome de quem escreveu ou por palavras da mensagem — vale para todas as abas': '按作者名字或消息中的关键词搜索评论——对所有标签页有效',
