    'De quanto em quanto tempo as mensagens novas entram no painel e no chat fixo — elas sempre aparecem suavemente, nunca todas de uma vez':
      '新消息进入面板和置顶聊天的时间间隔——它们总是平滑出现，绝不会一次全部涌入',
    'Espaço entre cada mensagem ao aparecer no painel e no chat fixo — cada uma entra com um efeito suave':
      '每条消息出现在面板和置顶聊天时的间隔——每条都以平滑效果进入',
    'Atualizar agora: solta as mensagens que estão aguardando (elas entram suavemente)': '立即刷新：释放正在等待的消息（它们会平滑进入）',
