    '🕘 Recuperar mensagens perdidas': '🕘 找回错过的消息',
    '— ao conectar (ou reconectar depois de uma queda), puxa o que cada serviço disponibiliza do chat recente': '——连接时（或掉线后重连时），拉取各服务提供的近期聊天记录',
    'A live caiu ou o programa ficou fechado? Ao voltar, o OBS Social busca as mensagens enviadas nesse meio-tempo — dentro do limite público de cada serviço: YouTube (as últimas dezenas que o chat guarda), Twitch (via o serviço comunitário recent-messages, o mesmo usado por apps como o Chatterino — só o nome do canal é consultado), Kick (as recentes da API do site) e Bilibili (as últimas ~10). Nada entra duplicado: mensagens repetidas são reconhecidas e ignoradas, e as recuperadas entram no fluxo suave normalmente.':
      '直播掉线了或程序被关闭了？恢复后，OBS Social 会在各服务的公开限制内找回这段时间发送的消息：YouTube（聊天保留的最近几十条）、Twitch（通过社区服务 recent-messages，与 Chatterino 等应用使用的相同——只查询频道名）、Kick（网站 API 的近期消息）和 Bilibili（最近约 10 条）。不会有重复：重复消息会被识别并忽略，找回的消息会正常进入平滑流动。',
    '📺 Bilibili (experimental)': '📺 Bilibili（实验性）',
    '— chat das lives da Bilibili, sem login': '——Bilibili 直播聊天，无需登录',
    'A Bilibili é a rede mais instável do OBS Social: sem login, ela pode abreviar nomes de usuários ou recusar a conexão (controle de risco deles). Ligue aqui para a Bilibili aparecer nas Conexões; desligando, a conexão é derrubada e o canal esquecido.':
      'Bilibili 是 OBS Social 中最不稳定的平台：不登录时，它可能会缩略用户名或拒绝连接（其风控机制）。在此开启后 Bilibili 会出现在连接页；关闭则断开连接并遗忘该频道。',

    // ---------- configurações: feedback / apoio / sobre ----------
    'Achou um problema? Tem uma ideia? Escreva aqui e envie para o desenvolvedor — o botão abre o seu programa de e-mail já com tudo preenchido.':
      '发现问题？有想法？在这里写下并发送给开发者——按钮会打开您的邮件程序并自动填好所有内容。',
    'Assunto': '主题',
    '💬 Feedback geral': '💬 一般反馈',
    '🐞 Problema ou erro (algo quebrou)': '🐞 问题或错误（有东西坏了）',
