    '🔌 Ajuda com as conexões (YouTube, Twitch, Kick, Bilibili)': '🔌 连接方面的帮助（YouTube、Twitch、Kick、Bilibili）',
    '🖥️ Ajuda com o OBS e os overlays': '🖥️ OBS 和覆盖层方面的帮助',
