    'Sua mensagem': '您的留言',
    'Conte o que aconteceu ou o que você gostaria de ver no OBS Social... Se for um problema, diga o que você estava fazendo quando aconteceu.':
      '说说发生了什么，或者您希望在 OBS Social 中看到什么… 如果是问题，请说明它发生时您正在做什么。',
    '📧 Enviar por e-mail': '📧 通过邮件发送',
    'Ou mande direto para': '或直接发送到',
    'Copiar e-mail': '复制邮箱',
    'O botão acima abre o seu aplicativo de e-mail com a mensagem pronta (a versão do programa vai junto, para ajudar a investigar). Se preferir, copie o endereço e envie de onde quiser.':
      '上方按钮会打开您的邮件应用并备好邮件（程序版本会附上，以便排查）。如果您愿意，也可以复制地址后从任意地方发送。',
    'Escreva a sua mensagem primeiro 🙂': '请先写下您的留言 🙂',
    '— enviado do OBS Social': '——发自 OBS Social',
    'O OBS Social é gratuito e sempre será. Se ele te ajuda nas lives e você quiser retribuir, qualquer valor é bem-vindo — basta apontar a câmera do celular para um dos QR codes. Muito obrigado! 💜':
      'OBS Social 是免费的，并将永远免费。如果它对您的直播有帮助，您想回馈的话，任何金额都欢迎——用手机相机对准其中一个二维码即可。非常感谢！💜',
    '🟣 NuBank (Pix)': '🟣 NuBank（Pix）',
    'QR em breve': '二维码即将推出',
    'Dá para apontar a câmera do celular para o QR,': '可以用手机相机对准二维码，',
    'abrir o link': '打开链接',
    'direto ou': '，或者',
    'e mandar para quem quiser. O do NuBank funciona com Pix de qualquer banco.': '并发送给任何人。NuBank 的二维码支持任意银行的 Pix。',
    '🔗 abrir': '🔗 打开',
    '📋 copiar código Pix': '📋 复制 Pix 代码',
    '📋 copiar link': '📋 复制链接',
    '✅ copiado!': '✅ 已复制！',
    'Painel de comentários de lives para o OBS Studio — YouTube, Twitch, Kick e Bilibili juntos, sem login e sem chave de API. Gratuito, feito com carinho para a comunidade de lives do Brasil.':
      '面向 OBS Studio 的直播评论面板——YouTube、Twitch、Kick 和 Bilibili 合而为一，无需登录、无需 API 密钥。免费，用心为巴西直播社区打造。',
    '👩‍💻 Criadores': '👩‍💻 创作者',
    '(IA da Anthropic) — projetou e escreveu o programa.': '（Anthropic 的 AI）——设计并编写了本程序。',
    "(Ward'z de Souza) — idealizador: teve a visão, dirigiu cada recurso e testou tudo nas lives.": "（Ward'z de Souza）——发起人：提出了愿景，主导了每个功能，并在直播中测试了一切。",
    '🔄 Atualização': '🔄 更新',
    '🔄 Verificar se há versão nova': '🔄 检查是否有新版本',
    '⬇️ Atualizar agora': '⬇️ 立即更新',
    'O programa verifica no GitHub e só instala se você confirmar — nada é instalado sozinho. Suas configurações, senha, logs e mídias ficam intactos, e ao atualizar ele fecha e abre sozinho.':
      '程序会在 GitHub 上检查，只有您确认后才会安装——绝不会自行安装。您的设置、密码、日志和媒体都会保持完好，更新时它会自动关闭并重开。',
    '🔁 Procurar atualização sozinho': '🔁 自动检查更新',
    'ao abrir o programa': '程序启动时',
    '1x por dia': '每天 1 次',
    ', e me avisar quando houver versão nova (nunca instala sem a sua confirmação)': '，有新版本时通知我（未经您确认绝不安装）',
    '📜 O que mudou em cada versão': '📜 各版本的更新内容',
    '◀ mais novas': '◀ 较新',
    'mais antigas ▶': '较早 ▶',
    'Não consegui carregar o histórico de versões.': '无法加载版本历史。',
