    'Instalar a atualização agora? Suas configurações, senha, logs e mídias ficam intactos. Depois de instalar, feche a janela preta do OBS Social e abra de novo para concluir.':
      '现在安装更新？您的设置、密码、日志和媒体都会保持完好。安装后，请关闭 OBS Social 的黑色窗口并重新打开以完成。',
