    "Ligado, o widget vira uma caixa de tamanho fixo e as partes dele (número, título, barra...) viram peças arrastáveis no 🖱️ Organizar a tela — clique no retângulo do widget para vê-las. Os widgets adicionais (QR 2, Winstreak 2...) seguem as mesmas peças da família.": "开启后，小组件变成固定大小的盒子，它的各部分（数字、标题、进度条等）在 🖱️ 整理屏幕里变成可拖动的拼块 — 点击小组件的矩形即可看到。额外小组件（QR 2、Winstreak 2 等）沿用同一家族的拼块设置。",
