    "TUDO do Organizar de volta ao padrão de fábrica: posições, tamanhos, camadas, peças e arte (dá para desfazer)": "整理屏幕的一切回到出厂默认：位置、大小、图层、拼块和美术（可以撤销）",
    "→ \"Fundo do comentário em destaque\". Assim que ela é ativada, aparece a peça": "→“突出评论背景”。一激活就会以拼块出现：",
    "dentro do Destaque no 🖱️": "（在 🖱️ 整理屏幕的突出卡片里）",
    "(e nas Camadas) — arraste, estique, gire e escolha o encaixe dela por lá, com ou sem o 🧩 ligado. A receita para a arte virar o cartão INTEIRO:": "（也在图层里）— 在那里拖动、拉伸、旋转并选择适配，🧩 开关均可。让美术变成整张卡片的配方：",
    "— e você arrasta cada peça para o lugar certo dela.": "— 每个拼块由你拖到合适的位置。",
    "do Organizar a tela para ver. Assim que a arte é ativada, ela vira a peça": "（在整理屏幕里）。美术一激活就变成拼块：",
    "— dá para arrastar, esticar, girar e escolher o encaixe, como qualquer outra peça. E para a arte virar o cartão inteiro (sem o fundo padrão, com cada peça onde você quiser), ligue": "— 可以拖动、拉伸、旋转并选择适配，和其他拼块一样。想让美术变成整张卡片（没有默认背景、拼块随意摆放），请打开：",

