    "— suas imagens e vídeos como fundo do cartão do destaque, moldura de tela inteira e fundo dos widgets": "— 你的图片和视频，作为突出卡片背景、全屏边框和小组件背景",
    "Desligado, nenhuma arte sua aparece na tela (as escolhas ficam guardadas para quando religar). Ligado, envie qualquer imagem ou vídeo e escolha": "关闭时，你的美术不会出现在屏幕上（选择会保留到再次打开）。打开后，上传任意图片或视频并选择位置",
    "— um seletor para cada overlay/widget. Para moldura de tela inteira, crie em 1920×1080 com fundo transparente (PNG ou WebM). Posição e tamanho se ajustam no mapa": "— 每个覆盖层/小组件一个选择框。全屏边框请做成 1920×1080 透明背景（PNG 或 WebM）。位置和大小在地图里调整",
