    "🗄️ Seus dados — 💾 backup, ↩️ restauração e 🧹 limpeza": "🗄️ 你的数据 — 💾 备份、↩️ 恢复和 🧹 清理",
    "Cada item tem o botão": "每一项都有按钮：",
