    "dele: escolha a frequência —": "：选择频率 —",
    "manual": "手动",
    "tempo real": "实时",
    "(grava assim que algo muda) ou um relógio de 1s a 24h — e o OBS Social copia o item para a pasta escolhida, numa sub-pasta com data e hora. O": "（一有变化就保存）或 1秒到24小时的定时 — OBS Social 会把该项复制到你选的文件夹里，放进带日期时间的子文件夹。",
    "↩️ Restaurar": "↩️ 恢复",
    "traz de volta o backup que você escolher. Um backup agendado só grava quando algo mudou de verdade, e os 30 mais recentes de cada item ficam guardados.": "按钮会带回你选择的备份。定时备份只有在真的有变化时才写入，每项保留最新的 30 份。",
    "💾 Pasta dos backups (à sua escolha — vazio = a pasta": "💾 备份文件夹（由你选择 — 留空 = 程序自己的",
