    "Cores, posições, widgets, peças, idioma, Labs... — tudo o que você configurou, num arquivo só.": "颜色、位置、小组件、拼块、语言、Labs… — 你配置的一切，都在一个文件里。",
    "💾 Backup:": "💾 备份：",
    "Manual (só no botão 💾)": "手动（仅通过 💾 按钮）",
    "Tempo real (assim que algo muda)": "实时（一有变化就备份）",
    "💾 Agora": "💾 立即",
    "nenhum ainda": "还没有",
    "exemplo: C:\\Users\\voce\\Documents\\Backups do OBS Social": "例如：C:\\Users\\你\\Documents\\OBS Social 备份",
    "Fazer o backup deste item agora": "立即备份这一项",
    "Qual backup restaurar (o mais novo primeiro)": "恢复哪个备份（最新在前）",
    "📜 Logs de comentários": "📜 评论日志",
    "Os arquivos de cada dia de live. Sem eles, um reinício não recupera o chat nem o sorteio do dia.": "每个直播日的文件。没有它们，重启后无法恢复当天的聊天和抽奖。",
    "🖼️ Mídias enviadas": "🖼️ 已上传的媒体",
    "Imagens e vídeos que você enviou para os overlays e widgets.": "你为覆盖层和小组件上传的图片和视频。",
    "✓ Marcas de leitura e fila": "✓ 已读标记和队列",
    "Quais comentários já foram para a tela e os que estão guardados na aba 📥 Fila.": "哪些评论已上过屏幕，以及保存在 📥 队列标签页里的评论。",
    "🎁 Participantes do sorteio": "🎁 抽奖参与者",
    "A lista de quem comentou e concorre no sorteio.": "评论过并参与抽奖的人的名单。",
    "🔌 Canais salvos": "🔌 已保存的频道",
    "Os canais lembrados de cada rede (o programa para de reconectar sozinho ao abrir).": "各平台记住的频道（程序启动时不再自动重连）。",
    "🧰 QR codes e winstreaks": "🧰 QR 码和连胜",
    "Seus QR codes salvos e os winstreaks (vitórias e recordes).": "你保存的 QR 码和连胜（胜场与纪录）。",
    "💣 Apagar tudo e voltar ao padrão de fábrica": "💣 删除全部并恢复出厂设置",
    "Apaga": "删除",
    "todos": "以上",
    "os itens acima": "全部项目",
    "devolve todas as configurações ao estado original (cores, posições, widgets, idioma, Labs...). É como reinstalar o programa. Sua senha de acesso pela rede é mantida, para você não ficar trancado fora — removê-la é uma opção separada, em 🔗 URLs para o OBS.": "把所有设置恢复到原始状态（颜色、位置、小组件、语言、Labs…）。相当于重装程序。你的网络访问密码会保留，免得被锁在外面 — 移除密码是另一个选项，在 🔗 OBS 专用 URL 里。",
    "Backup feito e guardado na pasta escolhida.": "备份完成，已存入所选文件夹。",
    "Nada mudou desde o último backup — nada foi gravado de novo.": "自上次备份以来没有变化 — 没有重复写入。",
    "Este item ainda está vazio — não há o que copiar.": "这一项还是空的 — 没有可复制的内容。",
    "Backup restaurado!": "备份已恢复！",
    "Backup restaurado! Os logs valem por inteiro depois de reiniciar o programa (botão ♻️ em 🔌 Conexões → Reiniciar conexões).": "备份已恢复！日志要在重启程序后才完全生效（🔌 连接 → 重启连接里的 ♻️ 按钮）。",
    "Restauração": "恢复",
    "Restaurar este backup?": "恢复这个备份？",
    "Os dados de AGORA deste item serão substituídos pelo que estava guardado no backup escolhido:": "这一项现在的数据将被所选备份里保存的内容替换：",
    "Restaurar": "恢复",
    "Este item ainda não tem nenhum backup na pasta.": "这一项在文件夹里还没有备份。",
