    "Deixe o OBS Social com a sua cara: cores, imagem de fundo, tamanhos de texto e de ícones, cantos e espaçamento. Isto muda o": "让 OBS Social 有你的风格：颜色、背景图、文字和图标大小、圆角和间距。改变的是",
