    "painel e nas configurações": "面板和设置",
    "na hora, em todos os aparelhos conectados. Os overlays do OBS (o conteúdo que o público vê) ficam como você desenhou.": "即时生效，覆盖所有已连接设备。OBS 覆盖层（观众看到的内容）保持你的设计。",
