    "Para baixa visão. Combina com o tema ⚡ Alto contraste da aba 🎨 Temas (preto + amarelo), que muda as cores da interface inteira.": "为低视力用户。可搭配 🎨 主题标签页的 ⚡ 高对比主题（黑+黄），它会改变整个界面的颜色。",
    "Reduzir animações": "减少动画",
    "— corta as animações e transições da interface": "— 关闭界面的动画和过渡",
    "Para quem tem sensibilidade a movimento (enjoo, epilepsia fotossensível, TDAH). As animações do overlay na live não mudam — elas são parte do seu show.": "为对运动敏感的人（晕动、光敏性癫痫、多动症）。直播中覆盖层的动画不变 — 那是你节目的一部分。",
