    "Para quem usa o teclado em vez do mouse (mobilidade reduzida, leitores de tela).": "为用键盘代替鼠标的人（行动不便、屏幕阅读器）。",
    "Formas além de cor no status": "状态不只靠颜色",
    "— a bolinha das conexões ganha ✓ (live no ar), ! (sem live) e ✕ (falhou)": "— 连接圆点获得 ✓（直播中）、!（无直播）和 ✕（失败）",
    "Para daltonismo: verde, amarelo e vermelho deixam de ser a única pista.": "为色盲用户：绿、黄、红不再是唯一线索。",
    "💡 Também ajudam (já existem em outras abas)": "💡 这些也有帮助（已在其他标签页）",
    "(no painel) amplia tudo de uma vez; o": "（面板里的）一次放大所有内容；",
    "Tamanho dos textos": "文字大小",
    "e a": "和",
    "fonte": "字体",
    "ficam na aba 🎨 Temas; os avisos importantes aparecem como texto (nunca só como som); e as dicas dos botões são lidas por leitores de tela. Falta algo para você? Conte na aba 📣 Feedback — acessibilidade é prioridade.": "在 🎨 主题标签页；重要警告始终以文字显示（绝不只用声音）；按钮提示可被屏幕阅读器朗读。还缺什么？在 📣 反馈标签页告诉我们 — 无障碍是优先事项。",
    "A conexão falhou": "连接失败",
