    "Tudo apagado: o OBS Social voltou ao padrão de fábrica e vai REINICIAR sozinho em instantes (pelo mesmo caminho da atualização). Esta página recarrega quando ele voltar.": "全部已删除：OBS Social回到出厂状态，马上会自行重启（走与更新相同的路径）。它回来后本页会自动刷新。",
    "Ao terminar, o programa REINICIA sozinho (como na atualização)": "完成后程序会自行重启（和更新时一样）",
    "Este é o MESMO pódio da tela do OBS (widget 🎁), com o mesmo dado 🎲 e as mesmas configurações — o suspense aqui é o do seu público. Fechar no ✖ acima não tira da tela.": "这就是OBS屏幕上的同一个领奖台（🎁小组件），同一颗骰子🎲、同样的设置——这里的悬念和观众的一样。上面的✖只在此处关闭，不会从屏幕上撤下。",
