    "Organizar a tela: posições, tamanhos e mídias (abre as configurações, aba 🎨 Temas)": "屏幕布置：位置、大小与媒体（打开设置的🎨主题标签页）",
    "Escreva um recado para aparecer na tela da live. A aparência (fonte, cores, tamanho, animações) fica em": "写一条要出现在直播屏幕上的消息。外观（字体、颜色、大小、动画）在这里：",
    "Configurações → 🎨 Temas": "设置 → 🎨主题",
    "O fuso horário fica em": "时区在这里：",
    "Estas opções também estão em Configurações → 🎨 Temas, junto da escolha do som.": "这些选项也在设置→🎨主题里，就在声音选择旁边。",
    "Se o ⏳ Timer estiver combinado com os Avisos, o recado sai sozinho quando o tempo acabar.": "若⏳计时器与公告联动，时间一到消息会自动撤下。",
