    "Ativar servidor WebSocket": "启用 WebSocket 服务器",
    "e copie a senha para cá. A conversa é toda dentro do seu computador — nada passa pela internet.": "并把密码复制到这里。整个对话都在你的电脑内部 — 什么都不经过互联网。",
    "Porta (a do OBS — padrão 4455)": "端口(OBS 的 — 默认 4455)",
