    "⚪ desligado (ligue o seletor acima)": "⚪ 关闭(打开上面的开关)",
    "A senha fica guardada só neste computador (na pasta": "密码只保存在这台电脑(文件夹",
    ") e nunca é enviada às telas. Quem acessa o painel pela rede só comanda o OBS se você liberar o seletor 🎬 no modo restrito (aba 🔒 Segurança) — de fábrica, fica bloqueado.": "),绝不发给任何屏幕。通过网络打开面板的人,只有你在受限模式放行 🎬 选择器时才能控制 OBS(🔒 安全标签)— 出厂即锁定。",
    "a que o OBS mostra": "OBS 显示的那个",
    "Salvar e conectar": "保存并连接",
    "🎵 Mesa de trilhas (experimental)": "🎵 音轨台(实验性)",
    "— botões de músicas e efeitos no painel; o som toca na live (pelo overlay no OBS), no painel, ou nos dois": "— 面板上的音乐和音效按钮;声音在直播(经 OBS 里的覆盖层)、面板、或两者播放",
    "Cada trilha é um botão na ferramenta 🎵 do painel (e do celular na mesma rede).": "每条音轨都是面板 🎵 工具里的一个按钮(同一网络的手机也有)。",
    "Uma por vez": "一次一条",
    ": apertar outra troca com fade; BGM pode repetir (🔁); o ⏹ para tudo. Para o som entrar NA LIVE, a fonte do overlay no OBS precisa estar com o áudio ativo (é o normal de uma fonte de navegador).": ": 按下另一条就淡入淡出切换;BGM 可循环(🔁);⏹ 停止全部。声音要进直播,OBS 里覆盖层来源的音频必须开启(浏览器来源的常态)。",
    "🎛️ Importar do Stream Deck (backup de perfis)": "🎛️ 从 Stream Deck 导入(配置文件备份)",
    "No programa Stream Deck:": "在 Stream Deck 程序里:",
    "Preferências → Perfis → exportar backup": "偏好设置 → 配置文件 → 导出备份",
    ". Os botões \"Tocar áudio\" viram trilhas prontas (nome, grupo, volume, 🔁 e fade). Os arquivos de som não vêm no backup — aponte a pasta deles aqui embaixo que eu encontro e copio sozinho.": "。\"播放音频\"按钮会变成现成的音轨(名称、分组、音量、🔁 和淡化)。音频文件不在备份里 — 在下面指定它们的文件夹,我自己找到并复制。",
    "Enviar um arquivo de som para virar trilha": "上传一个声音文件变成音轨",
    "Adicionar uma trilha com um som já enviado": "用已上传的声音添加音轨",
    "Emoji do botão": "按钮表情",
    "Nome da trilha": "音轨名称",
    "Grupo (pasta)": "分组(文件夹)",
    "Trilhas do mesmo grupo ficam juntas na mesa": "同组的音轨在台上排在一起",
    "Cor do botão": "按钮颜色",
    "Remover esta trilha": "移除这条音轨",
    "O arquivo de som desta trilha (envie novos no campo acima)": "这条音轨的声音文件(新的在上面的栏里上传)",
    "— escolher o som —": "— 选择声音 —",
    "Fade (segundos) na entrada, na troca e no ⏹": "淡化(秒): 开始、切换和 ⏹ 时",
    "Repetir sem parar (BGM)": "无限循环(BGM)",
    "Onde esta trilha toca": "这条音轨在哪播放",
    "📡 Na live": "📡 直播里",
    "🖥️ Só no painel": "🖥️ 只在面板",
    "📡+🖥️ Nos dois": "📡+🖥️ 两者",
    "Procurar os sons das trilhas pendentes nessa pasta": "在那个文件夹里找待定音轨的声音",
    "Importar do Stream Deck": "从 Stream Deck 导入",
    "Procurar os sons": "查找声音",
    "Escreva o caminho da pasta onde estão os arquivos de som.": "写下声音文件所在文件夹的路径。",
    "Esse arquivo é grande demais (limite: 64 MB). Exporte o backup SEM os áudios embutidos — os sons a gente encontra pela pasta.": "文件太大(上限: 64 MB)。导出不含内嵌音频的备份 — 声音我们通过文件夹找到。",
    "🎬 Comandar o OBS (cenas, transição, mudo, live/gravação)": "🎬 控制 OBS(场景、转场、静音、直播/录制)",
    "Como controlo as cenas do OBS pelo painel?": "如何从面板控制 OBS 场景?",
    "Ligue 🧪 Labs → 🎬 OBS Studio pelo painel (experimental). No OBS, ative Ferramentas → Configurações do Servidor WebSocket e copie a senha para o card do Labs. A ferramenta 🎬 do painel mostra as cenas (no modo estúdio, o clique escolhe o preview e o botão 🎬 manda para o ar), o mudo das fontes e a live/gravação — tudo dentro do seu computador, sem internet.": "打开 🧪 Labs → 🎬 从面板控制 OBS Studio(实验性)。在 OBS 里启用 工具 → WebSocket 服务器设置,把密码复制到 Labs 卡片。面板的 🎬 工具显示场景(工作室模式下点击选预览,🎬 按钮推上直播)、来源静音和直播/录制 — 全在你的电脑里,无需互联网。",
    "O que é a 🎵 Mesa de trilhas?": "什么是 🎵 音轨台?",
    "Uma mesa de som experimental (🧪 Labs): cada trilha vira um botão no painel — e no celular na mesma rede. Uma toca por vez, apertar outra troca com fade, BGM pode repetir (🔁) e o ⏹ para tudo. O som pode sair na live (pelo overlay no OBS), só no painel, ou nos dois. Dá até para importar os botões de som do seu Stream Deck, com um backup de perfis.": "一个实验性的声音台(🧪 Labs): 每条音轨变成面板上的按钮 — 同一网络的手机也有。一次播一条,按下另一条就淡入淡出切换,BGM 可循环(🔁),⏹ 停止全部。声音可以去直播(经 OBS 里的覆盖层)、只去面板、或两者。甚至能用配置文件备份导入你 Stream Deck 的声音按钮。",
    "🎵 Mesa de trilhas": "🎵 音轨台",
    "🎬 OBS Studio": "🎬 OBS Studio",
    "Mesa de trilhas (Labs)": "音轨台(Labs)",
    "Parar a trilha (com fade)": "停止音轨(带淡化)",
    "A mesa está vazia. As trilhas se cadastram em": "台子是空的。音轨在这里登记:",
    "Configurações → 🧪 Labs → 🎵 Mesa de trilhas": "设置 → 🧪 Labs → 🎵 音轨台",
    "— dá até para importar os botões do seu Stream Deck.": "— 甚至能导入你 Stream Deck 的按钮。",
    "Cada trilha toca onde o destino dela mandar: na live (pelo overlay no OBS), só no painel, ou nos dois. Uma por vez — apertar outra troca com fade.": "每条音轨按它的去向播放: 直播(经 OBS 里的覆盖层)、只在面板、或两者。一次一条 — 按下另一条就淡入淡出切换。",
    "tocando": "播放中",
    "(sem nome)": "(未命名)",
