    "A porta e a senha ficam em": "端口和密码在这里:",
    "Mandar a cena do preview para o ar (transição de estúdio)": "把预览场景推上直播(工作室转场)",
    "Trocar Tela (preview → ao vivo)": "交换画面(预览 → 直播)",
    "🔊 Fontes de áudio (toque para silenciar)": "🔊 音频来源(点按静音)",
    "Iniciar/encerrar a transmissão (pede confirmação)": "开始/结束直播(需要确认)",
    "Iniciar/encerrar a gravação (pede confirmação)": "开始/停止录制(需要确认)",
    "Iniciar transmissão": "开始直播",
    "Encerrar transmissão": "结束直播",
