    "Cenas (troca direto no ar)": "场景(直接切换直播)",
    "🟢 conectado": "🟢 已连接",
    "🟡 procurando o OBS...": "🟡 正在寻找 OBS...",
    "📡 AO VIVO": "📡 直播中",
    "📡 fora do ar": "📡 未直播",
    "⏺ gravando": "⏺ 录制中",
    "⏺ parado": "⏺ 已停止",
    "Encerrar a TRANSMISSÃO no OBS agora? A live sai do ar.": "现在结束 OBS 的直播?直播将下线。",
    "Iniciar a TRANSMISSÃO no OBS agora? Você entra AO VIVO.": "现在开始 OBS 的直播?你将上线直播。",
    "Parar a gravação no OBS?": "停止 OBS 的录制?",
    "Começar a gravar no OBS?": "在 OBS 开始录制?",
