    "🔴 o OBS pede senha — copie a senha em Ferramentas → Configurações do Servidor WebSocket": "🔴 OBS 需要密码 — 从 工具 → WebSocket 服务器设置 复制",
    "🔴 senha do OBS errada — confira em Ferramentas → Configurações do Servidor WebSocket": "🔴 OBS 密码错误 — 检查 工具 → WebSocket 服务器设置",
    "🔴 o OBS fechou a conexão — ele ainda está aberto?": "🔴 OBS 关闭了连接 — 它还开着吗?",
    "🔴 o OBS não respondeu — ele está aberto, com o WebSocket ligado?": "🔴 OBS 没有响应 — 它开着吗,WebSocket 启用了吗?",

