    "Editar a ordem dos botões (arraste um sobre o outro; a ordem vale também nas configurações)": "编辑按钮顺序(把一个拖到另一个上;顺序也适用于设置)",
    "✏️ Modo ordenar: arraste um botão sobre o outro para trocar de lugar. Clique no ✏️ de novo para voltar a tocar.": "✏️ 排序模式: 把一个按钮拖到另一个上即可交换位置。再点 ✏️ 回到播放。",
