    "Cada pessoa que abre o painel e as configurações vê tudo no idioma dela — a sua escolha aqui não muda o painel de ninguém. Já as telas do público (overlay e chat fixo no OBS) e a janela preta seguem a escolha feita aqui, para a live inteira.": "每个打开面板和设置的人都以自己的语言查看一切 — 你在这里的选择不会改变任何人的面板。而观众屏幕（OBS 里的叠加层和固定聊天）和黑色窗口则会跟随这里的选择，作用于整场直播。",
