    "Tipo da tecla": "按键类型",
    "🎵 Tecla de som": "🎵 声音键",
    "🎛️ Botão de multi ação": "🎛️ 多重动作按钮",
    "📁 Pasta simples": "📁 简单文件夹",
    "🎵 toca um som · 🎛️ Botão de multi ação: guarda teclas e o clique toca tudo em fila (segurar abre) · 📁 Pasta simples: só guarda teclas — o clique abre, nada toca": "🎵 播放一个声音 · 🎛️ 多重动作按钮：存放按键，点击按顺序播放全部（长按打开） · 📁 简单文件夹：只存放按键 — 点击打开，什么都不播放",
    "Nome (quebra de linha vale — até 50 letras)": "名称（可换行 — 最多 50 个字符）",
    "Vale na fila do 🎛️ botão de multi ação: depois desta tecla, o programa espera esse tempo e dispara a próxima.": "适用于 🎛️ 多重动作按钮的队列：此键之后，程序等待这段时间再触发下一个。",
    "🎛️ Segurar p/ abrir:": "🎛️ 长按打开:",
    "Um 🎛️ botão de multi ação toca tudo de dentro no clique; SEGURAR por este tempo abre ele (0 = abre no toque). A 📁 pasta simples sempre abre no toque.": "🎛️ 多重动作按钮点击时播放里面的全部内容；长按这段时间会打开它（0 = 点按即开）。📁 简单文件夹总是点按即开。",
    "Segundos segurando o botão de multi ação para abri-lo (0 a 5; 0 = abre no toque)": "长按多重动作按钮以打开它的秒数（0 到 5；0 = 点按即开）",
    ". Cada perfil vira um 🎛️ botão de multi ação da Mesa, e os botões \"Tocar áudio\" viram trilhas prontas dentro dele (nome, volume, 🔁 e fade). Os arquivos de som não vêm no backup — aponte a pasta deles aqui embaixo que eu encontro e copio sozinho.": "。每个配置文件变成面板上的一个 🎛️ 多重动作按钮，\"播放音频\"按钮变成它里面的现成音轨（名称、音量、🔁 和淡入淡出）。声音文件不在备份里 — 在下方指定它们的文件夹，我会自己找到并复制。",
    "Cor": "颜色",
    "Emoji": "表情符号",
    "Fade": "淡入淡出",
    "✏️ Modo ordenar: arraste um botão sobre outro para trocar de lugar; sobre uma 🎛️/📁 pasta para entrar nela; sobre o ⬅ para sair; sobre os ◀ ▶ para mudar de página. Clique no ✏️ de novo para voltar a tocar.": "✏️ 排序模式：把按钮拖到另一个上交换位置；拖到 🎛️/📁 文件夹上进入它；拖到 ⬅ 上离开；拖到 ◀ ▶ 上换页。再点一次 ✏️ 回到播放。",
    // ---------- v0.52.0: grade completa com ➕ e telinhas flutuantes ----------
    "Adicionar um botão aqui": "在这里添加一个按钮",
    "Adicionar um botão dentro desta pasta": "在这个文件夹里添加一个按钮",
    "Este é o MESMO pódio da tela do OBS (widget 🎁), com o mesmo dado 🎲 e as mesmas configurações — o suspense aqui é o do seu público. O 🗕 acima minimiza para a barra de cima (a tela do OBS continua como está); arraste pela parte de cima para mover.": "这和 OBS 屏幕上的领奖台一模一样（🎁 挂件），同样的骰子 🎲、同样的设置 — 这里的悬念和观众的一样。上面的 🗕 把它最小化到顶栏（OBS 屏幕保持原样）；按住顶部拖动即可移动。",
    "Minimizar (vira um chip na barra de cima; a tela do OBS continua como está)": "最小化（变成顶栏上的一个小片；OBS 屏幕保持原样）",
