    "Isto é uma assinatura, diferente das doações de cima: ela se repete todo mês até você cancelar (o cancelamento é na sua conta do LivePix, sem falar com ninguém). Nenhum recurso do programa depende disso — tudo continua grátis para todo mundo, sempre.": "这是订阅，和上面的捐赠不同：在你取消之前每月重复一次（取消在你自己的 LivePix 账户里完成，不需要联系任何人）。程序的任何功能都不依赖它 — 一切对所有人永远免费。",
