    "— o controle completo do OBS na ferramenta 🎬 do painel: transmitir, gravar (com pausa e marcador de capítulo), câmera virtual, replay, cenas, modo estúdio, transições, mostrar/esconder fontes, mixer de áudio, controle de mídia, filtros, coleções, perfis e print da tela. Tudo isso também vira": "— 在面板的 🎬 工具里完整控制 OBS：推流、录制（带暂停和章节标记）、虚拟摄像头、重放、场景、工作室模式、转场、显示/隐藏来源、音频混音器、媒体控制、滤镜、集合、配置文件和画面截图。这些也都能变成",
