    "🎬 Comandar o OBS (cenas, live/gravação, mixer, fontes, filtros, mídias — e as teclas 🎬 da Mesa)": "🎬 控制 OBS（场景、直播/录制、混音器、来源、滤镜、媒体 — 以及音板上的 🎬 按键）",
    "Como controlo o OBS pelo painel?": "我怎么从面板控制 OBS？",
    "Ligue 🧪 Labs → 🎬 OBS Studio pelo painel (experimental). Para linkar: no OBS (28+), abra Ferramentas → Configurações do Servidor WebSocket, marque Ativar servidor WebSocket, clique em Mostrar senha das conexões e copie a porta (4455) e a senha para o card do Labs — o passo a passo numerado está lá. Se o OBS estiver em OUTRO computador da rede, ponha o IP dele no campo Endereço (e libere a porta 4455 no firewall daquela máquina). A ferramenta 🎬 do painel comanda tudo: transmitir, gravar (com pausa e marcador de capítulo), câmera virtual, replay buffer, cenas, modo estúdio, transições, mostrar/esconder fontes, mixer de áudio, controle de mídia, filtros, coleções, perfis e print da tela — e cada bloco tem um liga/desliga no card do Labs, para a ferramenta ficar do tamanho que você usa. Tudo dentro do seu computador, sem internet.": "打开 🧪 Labs → 🎬 从面板控制 OBS Studio（实验性）。连接方法：在 OBS（28+）中打开 工具 → WebSocket 服务器设置，勾选 启用 WebSocket 服务器，点击 显示连接信息，把端口（4455）和密码复制到 Labs 卡片里 — 那里有编号的步骤。如果 OBS 在网络上的另一台电脑，请把它的 IP 填进地址栏（并在那台机器的防火墙上放行 4455 端口）。面板的 🎬 工具可以控制一切：推流、录制（带暂停和章节标记）、虚拟摄像头、重放缓存、场景、工作室模式、转场、显示/隐藏来源、音频混音器、媒体控制、滤镜、集合、配置文件和画面截图 — 而且每个板块在 Labs 卡片里都有开关，让工具正好是你需要的大小。全部在你的电脑里，不走互联网。",
    "Dá para transformar as coisas do OBS em botões?": "可以把 OBS 的功能变成按钮吗？",
    "Dá — é a tecla 🎬 Ação do OBS na 🎵 Mesa de trilhas. Crie uma tecla, escolha o tipo 🎬 e depois a ação (trocar de cena, gravar, mudo do microfone, mostrar uma fonte, ligar um filtro, tocar uma mídia...). As listas de cenas, fontes e filtros vêm do OBS conectado; o ▶ Testar agora dispara na hora para você conferir. A tecla acende sozinha quando o que ela controla está ligado (gravando, no ar, fonte visível). Essas teclas também entram dentro de um 🎛️ Botão de multi ação: a fila mistura som e comando — trocar de cena, esperar 2s e tocar a vinheta, por exemplo.": "可以 — 就是 🎵 音板上的 🎬 OBS 动作 按键。新建一个按键，选择类型 🎬，然后选择动作（切换场景、录制、麦克风静音、显示某个来源、启用某个滤镜、播放媒体……）。场景、来源和滤镜的列表来自已连接的 OBS；▶ 立即测试 会马上执行，方便你确认。当它控制的东西处于开启状态时（录制中、直播中、来源可见），按键会自己亮起。这些按键也能放进 🎛️ 多动作按钮里：队列可以混合声音和命令 — 例如切换场景、等 2 秒再播放片头。",
