    // ---------- v0.54: 🎭 perfis de overlay ----------
    "🎭 Perfis de overlay": "🎭 叠加层配置",
    "Um perfil é um": "一个配置就是一套",
    "molde completo": "完整的模板",
    "do comentário em destaque — cores, letra, arte, posição e as peças — guardado com um nome. Monte o visual no card 🎨 acima (e no 🖱️ Organizar a tela), salve como perfil e troque o overlay inteiro em um clique. E com o 🎭 automático, cada comentário destacado veste o molde certo sozinho: um para os comentários comuns e um por": "——把置顶评论的颜色、字体、素材、位置和各个部件，用一个名字保存下来。在上面的 🎨 卡片（以及 🖱️ 整理画面）里做好外观，存为配置，一键就能给整个叠加层换装。开启 🎭 自动后，每条被置顶的评论都会自己穿上对的模板: 普通评论一个，另外每个",
