    "só o destaque": "置顶评论本身",
    "(o cartão do comentário, com as peças e a arte dele) — widgets, chat fixo e o resto da tela ficam como estão. Para ajustar um perfil: ✨ Usar este → mexa à vontade nos cards e no 🖱️ → 💾 Regravar.": "（评论卡片，连同它的部件和素材）——小组件、固定聊天和画面的其他部分保持原样。要调整某个配置: ✨ 用这个 → 随意调整各卡片和 🖱️ → 💾 覆盖保存。",
    "Troca automática": "自动切换",
    "— cada comentário destacado veste o perfil certo sozinho": "——每条被置顶的评论都会自己穿上对的配置",
    "Super Chats e 💝 doações vestem o perfil da": "Super Chat 和 💝 打赏按金额穿上",
    "maior faixa alcançada": "达到的最高档位",
    "pelo valor — em qualquer moeda: o programa converte para reais pela cotação do dia. Comentário comum veste o perfil escolhido abaixo. Sem perfil que sirva (ou moeda sem cotação e sem faixa \"a partir de R$ 0\"), fica o visual de sempre.": "的配置——任何货币都行: 程序按当日汇率折算成雷亚尔。普通评论穿下面选的配置。没有合适的配置时（或货币没有汇率、又没有「从 R$ 0 起」的档位），就保持平时的外观。",
    "💬 Comentário comum (sem valor) veste": "💬 普通评论（无金额）穿",
    "— o visual de sempre —": "—— 平时的外观 ——",
    "💰 Faixas por valor (Super Chat e 💝 doação)": "💰 按金额分档（Super Chat 和 💝 打赏）",
    "a partir de": "从",
