    "Preenche as 6 faixas clássicas do Super Chat: a partir de R$ 1, 5, 10, 20, 50 e 100 (você escolhe o perfil de cada uma)": "填入 Super Chat 的 6 个经典档位: 从 R$ 1、5、10、20、50、100 起（每档的配置由你来选）",
