    "tanto, use tal perfil. O 🧪 de cada linha coloca no ar um Super Chat de teste com aquele valor, para você ver o molde vestido de verdade (tire do ar antes da live).": "起，用某个配置。每行的 🧪 会把一条该金额的测试 Super Chat 放上直播画面，让你看到模板真正穿上的样子（开播前记得把它撤下来）。",
    "O que são os 🎭 Perfis de overlay?": "什么是 🎭 叠加层配置？",
    "Moldes completos do comentário em destaque — cores, letra, arte, posição e as peças — salvos com um nome, no card 🎭 da aba Aparência. Monte o visual, salve como perfil e troque o overlay inteiro em um clique. Com a": "置顶评论的完整模板——颜色、字体、素材、位置和部件——用一个名字保存在「外观」页的 🎭 卡片里。做好外观，存为配置，一键给整个叠加层换装。开启",
    "troca automática": "自动切换",
    "ligada, cada comentário destacado veste o molde certo sozinho: um perfil para os comentários comuns e um por": "后，每条被置顶的评论都会自己穿上对的模板: 普通评论一个配置，每个档位各一个——",
    "Tamanho do comentário de exemplo, em letras — para testar se um comentário comprido cabe no seu overlay (muda no ar na hora)": "示例评论的长度（字数）——用来测试一条很长的评论能不能装进你的叠加层（直播画面上立刻变化）",
