    "⚠️ Dê um nome para o perfil primeiro (o campo à esquerda).": "⚠️ 先给配置起个名字（左边的输入框）。",
    "⚠️ O limite é 40 perfis — apague algum para criar outro.": "⚠️ 上限是 40 个配置——删掉一个才能再建。",
