    "Envie qualquer imagem ou vídeo e escolha": "上传任意图片或视频，然后选择",
    ", logo acima. E com um molde em edição no 🖱️, escolher o": "（就在上面）。而当 🖱️ 里有模板在编辑时，选择",
    "grava a arte DENTRO do perfil — cada molde com a sua arte.": "会把素材存进配置里 — 每个模板配自己的素材。",
