    "dentro do Destaque no 🖱️ — dá para arrastar, esticar, girar e escolher o encaixe, como qualquer outra peça. Para a arte virar o cartão inteiro, ligue": "在 🖱️ 的置顶评论里 — 可以拖动、拉伸、旋转、选择贴合方式，和其他部件一样。要让素材变成整张卡片，就打开下面的",
    "🎭 Editando": "🎭 编辑中",
    "— Visual ao vivo —": "— 直播外观 —",
    "✏️ Os ajustes do destaque estão gravando no molde": "✏️ 置顶评论的调整正在存入模板",
    "— a live só muda quando o 🎭 automático vestir este perfil (ou numa URL /overlay?perfil=...).": "— 只有当 🎭 自动给直播穿上这个配置（或在 /overlay?perfil=... 的网址上）时，直播才会变。",
    "Na aba Aparência (🎨 Temas), seção": "在「外观」页（🎨 主题），版块",
