    "Dá — é a tecla": "可以 — 就是",
    "na 🎵 Mesa de trilhas. Crie uma tecla, escolha o tipo 🎬 e depois a ação (trocar de cena, gravar, mudo do microfone, mostrar uma fonte, ligar um filtro, tocar uma mídia...). As listas de cenas, fontes e filtros vêm do OBS conectado; o ▶ Testar agora dispara na hora para você conferir. A tecla": "键（在 🎵 音轨台）。建一个键，选 🎬 类型再选动作（切换场景、录制、麦克风静音、显示来源、开关滤镜、播放媒体...）。场景、来源和滤镜列表来自已连接的 OBS；▶ 立即测试 马上触发方便检查。这个键",
    "acende sozinha": "会自己亮起",
    "quando o que ela controla está ligado (gravando, no ar, fonte visível). Essas teclas também entram dentro de um 🎛️ Botão de multi ação: a fila mistura som e comando — trocar de cena, esperar 2s e tocar a vinheta, por exemplo.": "当它控制的东西开着时（录制中、直播中、来源可见）。这些键也能放进 🎛️ 多动作按钮: 队列把声音和命令混在一起 — 比如切场景、等 2 秒、放片头曲。",
    "🎨 Temas → 🖼️ Suas artes": "🎨 主题 → 🖼️ 你的素材",
    ", na aba Aparência).": "（在外观页）。",
    "⚠️ Você está EDITANDO um molde no 🖱️ — volte para «— Visual ao vivo —» antes de vestir um perfil na live.": "⚠️ 你正在 🖱️ 里编辑模板 — 给直播穿配置之前，请先回到「— 直播外观 —」。",
    "Escolha um som primeiro (envie o arquivo em 🎨 Temas → 🖼️ Suas artes).": "先选一个声音（在 🎨 主题 → 🖼️ 你的素材 上传文件）。",
