    "🎯 Faixas — por 💰 valor, 🎨 cor do Super Chat ou 🔤 palavra no nome": "🎯 档位 — 按 💰 金额、🎨 Super Chat 颜色或 🔤 名字里的词",
    "Cada faixa escolhe COMO casar: 💰 a partir de um valor em reais (Super Chat e 💝 doação, qualquer moeda); 🎨 pelo tom que o próprio YouTube pintou no Super Chat; ou 🔤 por uma palavra que aparece no espaço do nome (o nome, «Membro», o nível do canal...). Quando mais de uma serve, a ordem é: cor → valor → palavra → comentário comum.": "每个档位选择「怎么匹配」: 💰 从某个雷亚尔金额起（Super Chat 和 💝 打赏，任何货币）; 🎨 按 YouTube 自己给 Super Chat 涂的颜色; 或 🔤 按名字区域出现的词（名字、「会员」、频道等级...）。多个都符合时，顺序是: 颜色 → 金额 → 词 → 普通评论。",
