    "Como controlo o vMix pelo painel?": "如何从面板控制 vMix？",
    "Dá para transformar as coisas do vMix em botões?": "能把 vMix 的功能变成按钮吗？",
    "🕒 tempo de membro (YouTube)": "🕒 会员时长（YouTube）",
    "meses de membro": "个月会员",
    "Meses como membro (0 = membro novo). O YouTube troca o selo em 1, 2, 6, 12, 24, 36... meses.": "会员月数（0 = 新会员）。YouTube 在第 1、2、6、12、24、36…个月更换徽章。",
    "🎯 Faixas — por 💰 valor, 🎨 cor do Super Chat, 🔤 palavra no nome ou 🕒 tempo de membro": "🎯 档位 — 按 💰 金额、🎨 超级留言颜色、🔤 名字中的词或 🕒 会员时长",
    "Cada faixa escolhe COMO casar: 💰 a partir de um valor em reais (Super Chat, 🎟️ Super Sticker e 💝 doação, qualquer moeda); 🎨 pelo tom que o próprio YouTube pintou no Super Chat ou no Super Sticker; 🔤 por uma palavra que aparece no espaço do nome (o nome, «Membro», o nível do canal...); ou 🕒 a partir de tantos meses como membro do YouTube (o tempo que o selo do membro mostra: novo, 1, 2, 6, 12, 24 meses...). Quando mais de uma serve, a ordem é: cor → valor → palavra → tempo de membro → comentário comum.": "每个档位选择匹配方式：💰 从某个雷亚尔金额起（超级留言、🎟️ 超级贴纸和 💝 捐赠，任何货币）；🎨 按 YouTube 自身为超级留言或超级贴纸涂的色调；🔤 按名字区域出现的词（名字、\"会员\"、频道等级……）；或 🕒 从 YouTube 会员的若干个月起（会员徽章显示的时长：新会员、1、2、6、12、24 个月……）。多个匹配时顺序为：颜色 → 金额 → 词 → 会员时长 → 普通评论。",
    "🔑 Palavras para participar (até 30)": "🔑 参与关键词（最多 30 个）",
    "Com palavras na lista, só entra no sorteio quem digitar uma delas no chat. Lista vazia: todo mundo que fala entra.": "列表中有关键词时，只有在聊天中输入其中一个的人才能参加抽奖。列表为空：所有发言的人都参加。",
    "Com palavras na lista, só entra quem digitar": "列表中有关键词时，只有输入",
    "uma delas": "其中一个",
    "no chat — a palavra inteira, sem diferença entre maiúsculas e minúsculas («#sorteio» vale como «sorteio»). Lista vazia = todo mundo que fala entra, como sempre.": "的人才能参加——整个单词，不区分大小写（\"#抽奖\"等同于\"抽奖\"）。列表为空 = 和以前一样，所有发言的人都参加。",
    "ex.: sorteio": "例如：抽奖",
    "Nova palavra do sorteio": "新的抽奖关键词",
    "Adicionar esta palavra": "添加此关键词",
    "Tirar esta palavra": "移除此关键词",
    "Nenhuma palavra — todo mundo que fala no chat entra.": "没有关键词——所有在聊天中发言的人都参加。",
    "limite de 30 palavras": "最多 30 个关键词",
    "Voltar (desfaz o último ajuste do sorteio — vale também para o que foi mexido no botão 🎁 do painel)": "返回（撤销抽奖的最后一次调整——包括在面板 🎁 按钮中所做的更改）",
    "TUDO do sorteio de volta ao padrão: palavras, fichas, dado, som e resposta (dá para desfazer)": "抽奖的全部恢复默认：关键词、抽奖券、骰子、声音和回复（可撤销）",
    "📏 Pontilhado do modo medida": "📏 测量模式虚线",
    "Quanto o contorno pontilhado branco aparece enquanto você digita no seletor manual (modo medida). Preferência deste navegador.": "在手动尺寸框输入时（测量模式）白色虚线轮廓的显眼程度。此浏览器的偏好设置。",
    "Mais visível": "更明显",
    "Bem visível": "非常明显",
    "📺 Por rede — cada uma pode vestir o seu próprio molde de comentário comum": "📺 按平台 — 每个平台可以穿自己的普通评论模板",
    "Um molde marcado como exclusivo de uma rede (▶️ 💜 🟢 💙) nunca veste comentário de outra. Aqui você diz o que cada rede veste quando nenhuma faixa casa: o comum acima, um molde só dela ou o visual ao vivo (sem molde).": "标记为某个平台专属（▶️ 💜 🟢 💙）的模板绝不会穿在其他平台的评论上。在这里你指定当没有任何档位匹配时每个平台穿什么：上面的普通模板、该平台专属的模板，或直播外观（无模板）。",
    "💰 Super Chat ou doação que não casa com faixa nenhuma veste": "💰 不匹配任何档位的超级留言或捐赠穿",
    "— o mesmo do comentário comum —": "— 与普通评论相同 —",
    "— o visual ao vivo (sem molde) —": "— 直播外观（无模板）—",
    "— o mesmo do comentário comum da rede —": "— 与该平台的普通评论相同 —",
    "⚠️ O visual ao vivo (quem veste tudo que não casa com molde) está com a arte «{arte}». Se a ideia era a arte só nos moldes, tire-a do visual ao vivo:": "⚠️ 直播外观（穿在所有不匹配模板的评论上）带有画面\"{arte}\"。如果画面只想用在模板上，请把它从直播外观中移除：",
    "🎭 Editando:": "🎭 正在编辑：",
    "Qual visual do destaque esta aba ajusta: o visual ao vivo (sem molde) ou um molde salvo. É o mesmo seletor 🎭 Editando do 🖱️ Organizar a tela.": "此选项卡调整的高亮外观：直播外观（无模板）或已保存的模板。与 🖱️ 整理屏幕 中的 🎭 正在编辑 选择器相同。",
    "⚠️ O comentário no ar está vestindo o molde «{molde}» pelo 🎭 automático — o que você ajusta aqui vai para o visual ao vivo, que a tela NÃO está mostrando agora. Abra o molde para mudar o que está na tela.": "⚠️ 正在播出的评论通过 🎭 自动 穿着模板\"{molde}\"——你在这里的调整会进入直播外观，而屏幕现在并没有显示它。请打开该模板来更改屏幕上的内容。",
    "⚠️ O comentário no ar está vestindo o molde «{molde}» pelo 🎭 automático — você está ajustando «{editando}». Abra «{molde}» para mudar o que está na tela.": "⚠️ 正在播出的评论通过 🎭 自动 穿着模板\"{molde}\"——你正在调整\"{editando}\"。请打开\"{molde}\"来更改屏幕上的内容。",
    "🎭 Abrir «{molde}»": "🎭 打开\"{molde}\"",
