    "Como está = do jeito que é de fábrica": "保持原样 = 出厂外观",
    "Cor própria deste texto (por cima das cores gerais do overlay)": "此文字自己的颜色（覆盖叠加层的整体颜色）",
    "Formatação deste texto de volta ao padrão": "将此文字的格式恢复默认",
    "📢 Texto do aviso": "📢 公告文字",
    "Vale em qualquer modo (cartão padrão, molde com arte ou overlay em peças) — é a mesma formatação da linha ✍️ do 🖱️ Organizar a tela.": "在任何模式下都有效（默认卡片、带素材的模板或部件化叠加层）——与 🖱️ 整理屏幕 中 ✍️ 行的格式相同。",
    "Vale com o widget nos presets de sempre ou solto em peças — é a mesma formatação da linha ✍️ do 🖱️ Organizar a tela.": "无论小组件处于常规预设还是拆成部件都有效——与 🖱️ 整理屏幕 中 ✍️ 行的格式相同。",
    "Cada texto do chat tem a sua formatação: o nome de quem comenta e o texto do comentário.": "聊天中的每个文字都有自己的格式：评论者的名字和评论文本。",
    "Contorno da letra (px) e a cor dele": "文字描边（px）及其颜色",
    "Espaço entre as letras (px)": "字距（px）",
    "Cor do contorno": "描边颜色",
    "✍️ Formatação da letra: clique numa peça com texto (nome, texto, valor, títulos, números...) e os ajustes de fonte, negrito, contorno... aparecem aqui.": "✍️ 文字格式：点击带文字的部件（名字、文本、金额、标题、数字...），字体、粗体、描边...等设置会显示在这里。",
    "✍️ «{peca}» é imagem ou caixa, não tem letra para formatar — clique numa peça com texto (nome, texto, valor, títulos, números...).": "✍️ \"{peca}\"是图片或方框，没有可设置格式的文字——请点击带文字的部件（名字、文本、金额、标题、数字...）。",
    "A formatação vale só para esta peça — cada peça com texto tem a sua": "格式只对这个部件生效——每个带文字的部件都有自己的格式",
