    "Na live, este comentário vestiria o molde": "在直播中，这条评论会套用模板",
    "A prévia mostra o visual ao vivo, que é o que você está editando — para ajustar o molde, abra-o no seletor 🎭 Editando.": "预览显示的是你正在编辑的直播外观 —— 要调整模板，请在 🎭 编辑 选择器中打开它。",
    "Clique num overlay ou numa peça para ver e digitar as medidas dele.": "点击一个叠加层或部件，查看并输入它的尺寸。",
    "🧩 Clique numa peça do mapa para ajustá-la aqui (tamanho, caixa, giro, opacidade, cor...).": "🧩 点击地图上的部件即可在此调整（大小、方框、旋转、不透明度、颜色...）。",
