    // ---------- v0.59: textos sem comparações ----------
    "A sua tela (16:9) inteira como mesa de trabalho.": "你的整个 (16:9) 屏幕就是工作台。",
    "da tela 1920×1080.": "基于 1920×1080 屏幕。",
    "— junto dos 🎭 Perfis de overlay: envie a imagem ou o vídeo e escolha onde ela entra (fundo do destaque, moldura de tela inteira ou fundo de widget). Com uma arte no fundo do destaque, o overlay padrão sai de cena sozinho: a arte vira a peça 🖼️ Sua arte no Organizar a tela, com posição e tamanho ajustáveis — e, com um molde em edição no 🖱️, a arte escolhida grava dentro do perfil.": "— 就在 🎭 Overlay 模板旁边: 上传图片或视频，选择它出现的位置（精选背景、全屏边框或小组件背景）。精选背景有美术时，默认 overlay 会自己退场: 美术会变成「整理屏幕」里的 🖼️ 你的美术部件，位置和大小都能调 — 在 🖱️ 里编辑模板时，选中的美术会存进模板里。",
    "para Super Chats e 💝 doações — em qualquer moeda, convertida para reais pela cotação do dia. O 🧪 de cada faixa põe no ar um Super Chat de teste com aquele valor, para conferir antes da live.": "用于 Super Chat 和 💝 打赏 — 任何货币，按当日汇率换算成雷亚尔。每个档位的 🧪 会把该金额的测试 Super Chat 放上直播，开播前先确认。",
    "— colaborador de vários elementos para o OBS Social.": "— 为 OBS Social 贡献多个元素的协作者。",
    "📺 Rede do overlay": "📺 叠加层的平台",
    "🌐 Compartilhado (todas)": "🌐 共用(全部)",
    "▶️ Só YouTube": "▶️ 仅 YouTube",
    "💜 Só Twitch": "💜 仅 Twitch",
    "🟢 Só Kick": "🟢 仅 Kick",
    "💙 Só Bilibili": "💙 仅 Bilibili",
    "Este visual/molde é de qual rede? O 🎭 automático só veste o molde em comentários da rede escolhida — compartilhado serve para todas": "这个视觉/模板属于哪个平台?🎭 自动模式只给所选平台的评论穿上模板 — 共用适用于全部平台",
    "💠 Pix direto do banco (experimental)": "💠 银行直连 Pix(实验性)",
    "— cada Pix recebido na sua conta vira um apoio na aba 💝 Apoios do painel, com a mensagem que a pessoa escreveu no app do banco": "— 收到的每笔 Pix 都会变成面板 💝 支持标签里的一条支持,并带上对方在银行应用里写的留言",
    "Sem intermediário e sem taxa de plataforma: o programa consulta a": "没有中间商、没有平台费:程序会定期查询",
    "API Pix do SEU banco": "你的银行的 Pix API",
    "(padrão do Banco Central) de tempos em tempos. Você precisa criar um aplicativo no portal do desenvolvedor do banco e colar aqui as credenciais e o certificado que ele fornecer. Perfis prontos:": "(央行标准)。你需要在银行的开发者门户创建一个应用,并把它提供的凭据和证书粘贴到这里。现成档案:",
    "(conta PJ — MEI serve; certificado sai de graça no portal) e": "(企业账户 — MEI 即可;证书在门户免费签发)和",
    "(PJ e": "(企业和",
