    "; usa certificado ICP-Brasil no CPF/CNPJ). Outro banco que siga o padrão? Use o perfil personalizado.": ";使用 CPF/CNPJ 的 ICP-Brasil 证书)。其他遵循该标准的银行?请使用自定义档案。",
