    "⚠️ o motor de transcrição ainda não está pronto (Configurações → Conexões) — clique para tentar de novo": "⚠️ 转写引擎尚未就绪(设置 → 连接)— 点击重试",
    "⚠️ este formato precisa do conversor ffmpeg (Configurações → Conexões) — clique para tentar de novo": "⚠️ 此格式需要 ffmpeg 转换器(设置 → 连接)— 点击重试",
