    "💬 WhatsApp (experimental)": "💬 WhatsApp(实验性)",
    "— as pessoas falam direto com o número da live (e/ou num grupo), e tudo cai numa coluna própria do painel: texto, foto, áudio, vídeo e documento, com prévia, transcrição, resposta assinada e ⏳ timeout / 🚫 banimento direto da coluna": "— 大家直接和直播号码对话(和/或在群里),一切都会进入面板的专属栏目:文字、照片、音频、视频和文档,可预览、可转写、可署名回复,还能直接在栏目里 ⏳ 禁言 / 🚫 封禁",
    "Leia antes de ligar:": "开启前请阅读:",
    "este conector usa o gateway": "此连接器使用",
    "(pago), que NÃO é oficial da Meta — é engenharia reversa do protocolo, e existe": "(付费)网关,它不是 Meta 官方的 — 是协议逆向工程,存在",
    "risco real de banimento do número": "号码被封禁的真实风险",
    "usado. Use um": "。请使用",
    "número SECUNDÁRIO dedicado à live": "专用于直播的备用号码",
    ", nunca o seu pessoal. Ligue aqui e configure o token em 🔌 Conexões. A mídia dos inscritos fica em quarentena na pasta": ",千万不要用个人号码。在这里开启并在 🔌 连接中配置令牌。订阅者的媒体会隔离在文件夹",
    "e só vai para a tela quando você mandar (botão direito → 📺); nomes que parecem telefone continuam mascarados na tela, como sempre. Uma opção por biblioteca aberta rodando no seu computador (sem gateway e sem mensalidade — mesmo risco) está a caminho.": "中,只有你发送时才会上屏(右键 → 📺);看起来像电话号码的名字照常在屏幕上打码。在你电脑上运行的开源库方案(无网关、无月费 — 风险相同)正在路上。",
    "Via gateway": "通过",
    "(pago, NÃO oficial da Meta): crie um canal no painel do Whapi, escaneie o QR com o": "(付费,非 Meta 官方)网关:在 Whapi 面板创建频道,用",
    "número da live": "直播号码",
    "e cole aqui o token do canal. ⚠️ Por não ser oficial, existe": "扫描二维码并把频道令牌粘贴到这里。⚠️ 由于并非官方,存在",
    "— use um número SECUNDÁRIO dedicado à live, nunca o pessoal. Conversas diretas com o número entram sempre; quer um grupo também? Preencha o campo do grupo. O ⏳ timeout vale pelo filtro do próprio OBS Social; o 🚫 banimento também bloqueia o número da pessoa no gateway.": "— 请使用专用于直播的备用号码,千万不要用个人号码。与号码的私聊总会进来;也想用群?填上群组字段。⏳ 禁言由 OBS Social 自身的过滤器保证;🚫 封禁还会在网关拉黑对方号码。",
    "token do canal (do painel do Whapi)": "频道令牌(来自 Whapi 面板)",
    "opcional — grupo: id (…@g.us) ou nome exato (vazio = diretas e qualquer grupo)": "可选 — 群组:id(…@g.us)或准确名称(留空 = 私聊和任何群)",
    "🌐 Gateway Whapi (pago — cole o token do canal)": "🌐 Whapi 网关(付费 — 粘贴频道令牌)",
    "🖥️ Biblioteca local (grátis — QR no seu computador, sem gateway)": "🖥️ 本地库(免费 — 在你的电脑上扫码,无网关)",
    "As duas formas usam o mesmo protocolo não oficial — o risco de banimento é igual; muda quem faz a ponte": "两种方式使用同一个非官方协议 — 封禁风险相同,不同的只是由谁来搭桥",
    "A biblioteca aberta (": "开源库(",
    ") roda 100% no seu computador — sem gateway e sem mensalidade, com o": ")100% 在你的电脑上运行 — 无网关、无月费,但",
    "mesmo risco": "风险相同",
    "de banimento (número SECUNDÁRIO sempre). Baixe a biblioteca uma vez, conecte e escaneie o QR que aparece aqui com o WhatsApp do número da live (Configurações → Aparelhos conectados). A sessão fica guardada e sobrevive a reinícios.": "(务必用备用号码)。下载一次库文件,连接后用直播号码的 WhatsApp 扫描这里出现的二维码(设置 → 已连接的设备)。会话会被保存,重启后依然有效。",
    "Baixar a biblioteca local agora (via npm, sob demanda)": "立即下载本地库(通过 npm,按需)",
    "Apagar a sessão pareada — para trocar de número ou recomeçar o pareamento": "删除已配对会话 — 用于更换号码或重新配对",
    "Apagar a sessão pareada (trocar de número)": "删除已配对会话(更换号码)",
    "📱 Escaneie com o WhatsApp do número da live: Configurações → Aparelhos conectados → Conectar aparelho.": "📱 用直播号码的 WhatsApp 扫描:设置 → 已连接的设备 → 连接设备。",
    "baixando a biblioteca... (pode levar um minuto)": "正在下载库…(可能需要一分钟)",
    "✔ biblioteca instalada — conecte e escaneie o QR": "✔ 库已安装 — 连接并扫描二维码",
