    "Apagar a sessão pareada do WhatsApp? Você vai precisar escanear o QR de novo.": "删除已配对的 WhatsApp 会话?你需要重新扫描二维码。",
    "e só vai para a tela quando você mandar (botão direito → 📺); nomes que parecem telefone continuam mascarados na tela, como sempre. Dá para escolher entre DOIS modos no card de Conexões: o gateway Whapi (pago) ou a biblioteca aberta rodando no seu computador (grátis, QR — mesmo risco).": "中,只有你发送时才会上屏(右键 → 📺);看起来像电话号码的名字照常打码。在连接卡片上可以选择两种模式:Whapi 网关(付费)或在你电脑上运行的开源库(免费、扫码 — 风险相同)。",
