    "🕐 sai quando o relógio chegar na data/hora preenchida · ⏳ sai quando faltar esse tempo no timer. Disparou uma vez, os números voltam a 00.": "🕐 时钟到达填入的日期/时间时消失 · ⏳ 倒计时剩余这么多时间时消失。触发一次后,数字回到 00。",
    "Se o ⏳ Timer estiver combinado com os Avisos, o recado também sai sozinho quando o tempo acabar.": "如果 ⏳ 倒计时与公告联动,时间结束时消息也会自动消失。",
