    "A conexão e o controle completo do OBS Studio pelo painel. Esta página fica disponível enquanto o seletor 🎬 estiver ligado na aba 🧪 Labs.": "通过面板连接并完全控制 OBS Studio。只要 🧪 Labs 标签页中的 🎬 开关处于开启状态,此页面就可用。",
