    "⚙️ Ligado, a configuração completa mora na página «🎬 OBS Studio Remoto» do menu à esquerda (logo depois de 🎨 Temas).": "⚙️ 开启后,完整配置位于左侧菜单的「🎬 OBS Studio 远程」页面(就在 🎨 主题之后)。",
    "⚙️ Ligada, a configuração completa mora na página «🎵 Mesa de Trilhas» do menu à esquerda (logo depois de 🎨 Temas).": "⚙️ 开启后,完整配置位于左侧菜单的「🎵 音轨台」页面(就在 🎨 主题之后)。",
    "A porta e a senha ficam na página «🎬 OBS Studio Remoto» das configurações.": "端口和密码在设置的「🎬 OBS Studio 远程」页面。",
