    "Qualquer coisa com atalho no OBS (até de plugin) dispara daqui — é o coringa do que ainda não tem botão próprio.": "OBS 里任何有快捷键的东西(包括插件的)都能从这里触发 — 是还没有专属按钮的功能的万能牌。",
