    "📊 Saúde do OBS: fps, CPU, memória, disco, quadros perdidos e tempos de transmissão/gravação": "📊 OBS 健康:fps、CPU、内存、磁盘、丢帧和直播/录制时长",
    "⌨️ Disparar atalhos do OBS por nome — o coringa do que não tem botão próprio (vem desligado)": "⌨️ 按名称触发 OBS 快捷键 — 没有专属按钮的功能的万能牌(默认关)",
    "🎬 Criar teclas do OBS na Mesa (escolha o que quiser)": "🎬 在音轨台创建 OBS 按键(想选什么选什么)",
    "Marque os recursos do seu OBS e aperte ➕: cada um vira uma tecla DE VERDADE na Mesa — dá para mover, renomear, colorir e apagar como qualquer outra. Depois de criar, é só arrastar cada tecla para a célula que quiser.": "勾选你 OBS 中的资源并按 ➕：每一个都会变成音轨台上的真正按键 —— 可以像其他按键一样移动、重命名、上色和删除。创建后，把每个按键拖到想要的格子即可。",
