    "O clique na tecla mostra a mídia no painel E no overlay (no overlay só a imagem/vídeo aparecem); clicar de novo tira. Na janela, o overlay contorna a mídia com a sombra dos overlays (a mesma do 🔍 mostrar avatar — ajuste em 🎨 Aparência). O vídeo sai sozinho quando termina.": "点击按键,媒体会同时出现在面板和叠加层上(叠加层只显示图片/视频);再点一次移除。窗口模式下,叠加层用叠加层阴影(与 🔍 显示头像相同 — 在 🎨 外观中调整)勾勒媒体。视频结束后自动消失。",
    "🎵 toca um som · 🖼️/🎞️ mostra uma imagem ou vídeo no painel e no overlay (janela redimensionável ou tela cheia) · 🎬 Ação do OBS: comanda o OBS Studio (gravar, trocar de cena, mudo...) · 🎛️ Botão de multi ação: guarda teclas e o clique toca tudo em fila (segurar abre) · 📁 Pasta simples: só guarda teclas — o clique abre, nada toca": "🎵 播放声音 · 🖼️/🎞️ 在面板和叠加层显示图片或视频(窗口或全屏) · 🎬 OBS 动作:控制 OBS Studio(录制、切换场景、静音…) · 🎛️ 多动作按钮:存放按键,点击按顺序播放全部(长按打开) · 📁 简单文件夹:只存放按键 — 点击打开,不播放任何东西",
    "✨ Sombra dos overlays": "✨ 叠加层阴影",
    "Suave — a do 🔍 mostrar avatar (padrão)": "柔和 — 🔍 显示头像的那种(默认)",
    "Contorno marcado": "明显轮廓",
    "Sem sombra": "无阴影",
    "Opacidade": "不透明度",
    "Contorna o 🔍 avatar, a 📎 mídia do inscrito, as 🖼️🎞️ mídias da Mesa de Trilhas e o 💬 cartão de destaque (com «Sombra no cartão» ligada) — o mesmo padrão em todos.": "勾勒 🔍 头像、📎 订阅者媒体、🖼️🎞️ 音轨台媒体和 💬 精选卡片(开启「卡片阴影」时)— 全部同一标准。",
    "Tirar a mídia da tela (painel e overlay)": "把媒体从屏幕移除(面板和叠加层)",
