    "Velocidade da mídia na tela do público (0.05× a 32×, de 0.01 em 0.01)": "观众屏幕上媒体的速度(0.05× 到 32×,步进 0.01)",
    "🥇 Nítida (padrão)": "🥇 清晰(默认)",
    "🌫️ Suavizada": "🌫️ 柔化",
    "🧱 Pixelada": "🧱 像素化",
    "Qualidade": "质量",
    "O arquivo tem uma qualidade só — este seletor muda o acabamento da exibição (vale no painel e no overlay)": "文件只有一种质量 — 此选择器改变显示的观感(面板和叠加层都生效)",
    "Velocidade do áudio (abre os ajustes finos)": "音频速度(打开精细调节)",
    "O clique na tecla mostra a mídia no painel E no overlay (no overlay só a imagem/vídeo aparecem); clicar de novo tira. Na janela, o overlay contorna a mídia com a sombra dos overlays (a mesma do 🔍 mostrar avatar — ajuste em 🎨 Aparência). O vídeo sai sozinho quando termina. Envie imagens e vídeos pelo ⬆️ enviar arquivo da própria Mesa: a biblioteca dela é separada da dos overlays.": "点击按键,媒体会同时出现在面板和叠加层上(叠加层只显示图片/视频);再点一次移除。窗口模式下,叠加层用叠加层阴影(与 🔍 显示头像相同 — 在 🎨 外观中调整)勾勒媒体。视频结束后自动消失。图片和视频通过音轨台自己的 ⬆️ 发送文件上传:它的媒体库与叠加层的分开。",
    "Enviar som, imagem ou vídeo para a biblioteca da Mesa — vira uma tecla na hora": "把声音、图片或视频发送到音轨台媒体库 — 立即变成按键",
    "📋 Copiar": "📋 复制",
