    "📌 Colar aqui": "📌 粘贴到这里",
    "📌 Colar aqui dentro": "📌 粘贴到此文件夹内",
    "✏️ Editor da tecla — arraste para mover · estique pelo canto": "✏️ 按键编辑器 — 拖动移动 · 从角落拉伸",
    "Maximizar / restaurar": "最大化 / 还原",
    "Subir um nível (a pasta de fora)": "上一层(外面的文件夹)",
    "Volume dos áudios e vídeos de dentro (%)": "内部音频和视频的音量(%)",
    "✔ Aplicar a todos de dentro": "✔ 应用到里面的全部",
    "Voltar um nível (segure uma tecla sobre ele no ✏️ ordenar para tirá-la desta pasta)": "返回上一层(在 ✏️ 排序中把按键按在它上面可将其移出此文件夹)",
    "✏️ Modo ordenar: arraste um botão sobre outro para trocar de lugar; sobre uma 🎛️/📁 pasta para entrar nela (até pasta dentro de pasta); sobre o ⬅ da barra para subir um nível; sobre os ◀ ▶ para mudar de página. Clique no ✏️ de novo para voltar a tocar.": "✏️ 排序模式:把按钮拖到另一个上交换位置;拖到 🎛️/📁 文件夹上进入(文件夹套文件夹也行);拖到栏上的 ⬅ 上一层;拖到 ◀ ▶ 换页。再点 ✏️ 恢复播放。",
    // ---------- v0.90.0: 📋 histórico do clipboard + 💾 backup da Mesa + 🔑 criptografia ----------
    "Escreva ou cole aqui e mande para o histórico — todo mundo com o painel aberto vê na hora.": "在这里输入或粘贴并发送到历史 — 打开面板的所有人立刻可见。",
    "Mandar o texto para o histórico (Ctrl+Enter)": "把文本发送到历史（Ctrl+Enter）",
    "Enviar texto": "发送文本",
    "Compartilhar um arquivo (qualquer tipo, sem limite de tamanho)": "分享文件（任何类型，大小不限）",
    "Arquivo": "文件",
    "Limpar o histórico inteiro": "清空全部历史",
    "⏳ Enviando o arquivo...": "⏳ 正在发送文件...",
    "Compartilhada com quem abrir este painel na mesma rede. Textos e arquivos, sem limite de tamanho.": "与同一网络中打开此面板的所有人共享。文本和文件，大小不限。",
    "texto longo": "长文本",
    "Copiar o texto inteiro": "复制全文",
    "Baixar o arquivo": "下载文件",
    "Tirar esta entrada do histórico": "把这条记录从历史中移除",
    "Não consegui mandar o arquivo.": "文件发送失败。",
    "Limpar o histórico inteiro da área de transferência (para todo mundo)? Os arquivos compartilhados saem junto.": "清空剪贴板的全部历史（对所有人）？共享的文件也会一起删除。",
    "Área de transferência": "剪贴板",
    "💾 Backup próprio da Mesa de Trilhas": "💾 音轨台专属备份",
    "📄 Simples (só a configuração)": "📄 简单（仅配置）",
    "📦 Total (com os arquivos)": "📦 完整（含文件）",
    "Baixa um .json só com as teclas (sem os arquivos)": "下载仅含按键的 .json（不含文件）",
    "Baixa um .zip com as teclas + todos os arquivos da biblioteca da Mesa": "下载含按键 + 音轨台媒体库全部文件的 .zip",
    "⏳ Restaurando...": "⏳ 正在恢复...",
    "O simples guarda só as teclas; o total inclui os arquivos da biblioteca da Mesa (e o que as teclas usam da geral). Restaurar um backup da Mesa substitui as teclas atuais; um backup do Stream Deck continua entrando por adição, como sempre. Só no computador do streamer.": "简单版只保存按键；完整版还包含音轨台媒体库的文件（以及按键从通用库使用的内容）。恢复音轨台备份会替换当前按键；Stream Deck 备份依旧以追加方式进入，一如既往。仅限主播的电脑。",
    ". Cada perfil vira uma 📁 pasta da Mesa com tudo dentro no lugar: as pastas do Stream Deck viram pastas aninhadas, cada Multi Action vira um 🎛️ botão de multi ação (as esperas viram o ⏱), os botões \"Tocar áudio\" viram trilhas prontas (nome, volume, 🔁 e fade), as ações do OBS Studio viram teclas 🎬 e a arte de cada tecla vem junto. Os arquivos de som não vêm no backup — aponte a pasta deles aqui embaixo que eu encontro e copio sozinho.": "。每个配置文件都会变成一个一切就位的 📁 文件夹：Stream Deck 的文件夹变成嵌套文件夹，每个 Multi Action 变成 🎛️ 多动作按键（等待变成 ⏱），\"播放音频\"按键变成现成的音轨（名称、音量、🔁 和淡入淡出），OBS Studio 的动作变成 🎬 按键，每个按键的图片也一起带来。声音文件不在备份里 — 在下面指出它们的文件夹，我会自己找到并复制。",
    "Com senha, quem abre o painel pela rede pode entrar com ela e aí controla tudo (os seletores acima valem para quem NÃO entrou). A senha vira um código embaralhado (hash scrypt com sal e custo alto) — nunca fica gravada em texto. E as outras senhas guardadas pelo programa (OBS, tokens de bot, Pix) ficam cifradas (AES-256) com uma chave que só existe neste computador. Só este computador pode definir, trocar ou remover.": "设置密码后，通过网络打开面板的人可以用它登录并控制一切（上面的开关适用于未登录的人）。密码会变成打乱的代码（加盐、高成本的 scrypt 哈希）— 绝不会以文本保存。程序保存的其他密码（OBS、机器人令牌、Pix）也会用只存在于这台电脑的密钥加密（AES-256）。只有这台电脑能设置、更改或删除。",
    ", cifrada com AES-256) e nunca é enviada às telas. Quem acessa o painel pela rede só comanda o OBS se você liberar o seletor 🎬 no modo restrito (aba 🔒 Segurança) — de fábrica, fica bloqueado.": "，用 AES-256 加密），绝不会发送到屏幕。通过网络访问面板的人只有在受限模式中打开 🎬 开关时才能控制 OBS（🔒 安全标签页）— 出厂即锁定。",
    ", cifradas com AES-256) e nunca são enviadas às telas. A primeira consulta boa apenas reconhece os Pix que já existiam — só os que chegarem DEPOIS viram apoio no painel. A mensagem do pagador é garantida nos Pix pagos por QR de cobrança; na transferência manual para a chave, depende do banco.": "，用 AES-256 加密），绝不会发送到屏幕。第一次成功查询只识别已存在的 Pix — 只有之后到达的才会成为面板上的支持。付款者的留言在通过收款二维码支付的 Pix 中有保证；手动转账到密钥则取决于银行。",
    "Restaurar este backup da Mesa? As teclas de AGORA serão substituídas pelas do backup (um backup do Stream Deck, se for o caso, só adiciona).": "恢复这个音轨台备份？现在的按键将被备份中的按键替换（如果是 Stream Deck 备份，则只会追加）。",
    "Backup da Mesa": "音轨台备份",
