    "O programa respondeu de um jeito que não entendi.": "程序的回应我看不懂。",
    "Modo restrito: área de transferência desativada pelo streamer.": "受限模式：主播关闭了剪贴板。",
    "Arquivo grande demais para quem entra pela rede (limite: 300 MB). No computador do streamer não há limite.": "对通过网络进入的人来说文件太大（上限 300 MB）。在主播的电脑上没有限制。",
    "O disco está quase cheio — libere espaço antes de compartilhar arquivos.": "磁盘快满了 — 分享文件前请先腾出空间。",
