    // ---------- v0.92.0: arte do perfil na barra e tira de moldes ----------
    "🖼️ Arte deste perfil": "🖼️ 这个模板的美术",
    "Envia a imagem ou o vídeo que vai ser o fundo deste perfil. Com um nome escrito ao lado, a arte espera e entra junto no ➕ Novo perfil; sem nome, ela veste na hora o molde que está aberto": "上传要作为这个模板背景的图片或视频。旁边写了名字时，美术会等着，跟 ➕ 新模板 一起进去；没写名字时，它立刻穿在当前打开的模子上",
    "arte à espera do perfil novo": "等待新模板的美术",
