    // ---------- v0.93.0: a arte é independente do cartão ----------
    "Arraste para esticar a arte — ela é independente do cartão padrão e pode passar dele (até 400%)": "拖动可拉伸美术 — 它独立于默认卡片，可以超出卡片（最多 400%）",
    // ---------- v0.94.0: peças soltas, 🎯 foco e 📋 copiar ajustes ----------
    "🎯 Só o que estou editando": "🎯 只显示正在编辑的",
    "Some com todo o resto do mapa e deixa só o overlay que você está editando (com as peças dele). É só aqui no editor: a live continua mostrando tudo.": "把地图上其他东西都藏起来，只留下你正在编辑的 overlay（连同它的部件）。只在编辑器里生效：直播照常显示全部。",
    "📋 Copiar ajustes para...": "📋 把调整复制到...",
    "Leva os ajustes deste molde (posições, tamanhos e peças) para outros moldes — cada um fica com a arte dele": "把这个模子的调整（位置、大小、部件）带到别的模子 — 每个模子保留自己的美术",
    "Copiar ajustes do molde": "复制模子的调整",
    "Marcar todos": "全选",
    "Levar a arte junto (troca a arte dos moldes marcados pela deste)": "把美术也带过去（用这个的美术替换所选模子的）",
    "Arraste para esticar a peça — ela é independente do cartão padrão e pode passar dele (até 400%)": "拖动可拉伸部件 — 它独立于默认卡片，可以超出卡片（最多 400%）",
    "Arraste para mudar o tamanho da peça — ela pode passar do cartão padrão (até 1000%)": "拖动可改变部件大小 — 它可以超出默认卡片（最多 1000%）",
    "Fora do foco 🎯 — clique para editar este overlay": "不在焦点内 🎯 — 点击编辑该叠加层",
    "automático": "自动",
    "0 = automático (a peça fica do tamanho do conteúdo dela)": "0 = 自动（部件与自身内容一样大）",
    "🎯 O que estou editando": "🎯 我正在编辑的",
